<script>
document.querySelectorAll('[data-phone]').forEach(group=>{const select=group.querySelector('[data-country]'),flag=group.querySelector('[data-flag]'),dial=group.querySelector('[data-dial]');const sync=()=>{const option=select.options[select.selectedIndex];flag.textContent=option?.dataset.flag||'🌐';dial.textContent=select.value||''};select.addEventListener('change',sync);sync()});
const manager=document.getElementById('manager'),managerEmail=document.getElementById('manager-email');const syncManager=()=>{if(managerEmail) managerEmail.value=manager?.selectedOptions?.[0]?.dataset?.email||''};manager?.addEventListener('change',syncManager);syncManager();
const salaryParts=[...document.querySelectorAll('.salary-part')],salaryTotal=document.getElementById('salary-total');const syncSalary=()=>{const total=salaryParts.reduce((sum,input)=>sum+(parseFloat(input.value)||0),0);salaryTotal.textContent=total.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})};salaryParts.forEach(input=>input.addEventListener('input',syncSalary));syncSalary();
</script>
